def are_dice_consecutive(d1, d2, d3):
    values = sorted([d1, d2, d3])
    return values[1] - values[0] == 1 and values[2] - values[1] == 1

def sum_odd_numbers():
    total = 0
    for i in range(1, 1000, 2):
        total += i
    return total

def harmonic_average(numbers):
    n = len(numbers)
    reciprocal_sum = 0

    for x in numbers:
        reciprocal_sum += 1 / x

    return n / reciprocal_sum

def total_movie_duration(movies):
    total_minutes = 0

    for hours, minutes in movies:
        if hours == 0 and minutes == 0:
            break
        total_minutes += hours * 60 + minutes

    return total_minutes // 60, total_minutes % 60

def count_read_numbers(numbers):
    count = 0
    previous = None

    for number in numbers[:10]:
        count += 1
        if previous is not None and number > previous:
            break
        previous = number

    return count

def reverse_digits(n):
    result = []

    while n > 0:
        result.append(str(n % 10))
        n //= 10

    return ' '.join(result)

def approximate_pi(n):
    total = 0

    for i in range(n):
        total += ((-1) ** i) / (2 * i + 1)

    return 4 * total

def check_voucher_promotion(vouchers):
    result = []

    a, b, c, d, e = vouchers

    if a + b + c == c + d + e:
        result.append('cashback')

    three_other_sum = b + c + d
    if three_other_sum != 0 and three_other_sum % (a + e) == 0:
        result.append('discount')

    return result

def battle_result(vikings, saxons):
    viking_power = vikings * 4

    if viking_power > saxons:
        return 'Viking won'
    elif viking_power < saxons:
        return 'Saxon won'
    else:
        return 'Stand off'

def battle_result(turks, mongols):
    turk_power = turks * 3

    if turk_power > mongols:
        return 'Turk won'
    elif turk_power < mongols:
        return 'Mongol won'
    else:
        return 'neither won'

def find_largest(a, b, c):
    if a >= b and a >= c:
        return a
    elif b >= a and b >= c:
        return b
    else:
        return c

def classify_triangle(a, b, c):
    sides = sorted([a, b, c])
    x, y, z = sides

    if x + y <= z:
        return 'Not a triangle'

    if x == y == z:
        return 'Equilateral triangle'

    if x * x + y * y == z * z:
        return 'Right triangle'

    if x == y or y == z:
        return 'Isosceles triangle'

    if x * x + y * y > z * z:
        return 'Acute triangle'

    return 'Obtuse triangle'

def evaluate_quadratic(a, b, c):
    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        return 'Has two valid roots'
    elif discriminant == 0:
        return 'Has one valid root'
    else:
        return 'Has no root'

def count_vowels(text):
    vowels = 'aeiouAEIOU'
    count = 0

    for char in text:
        if char == '.':
            break
        if char in vowels:
            count += 1

    return count

def count_all_odd_throws(throws):
    count = 0

    for dice in throws:
        if sum(dice) == 10:
            break

        if all(value % 2 == 1 for value in dice):
            count += 1

    return count

def find_min_position(numbers):
    min_value = None
    min_position = 0
    position = 0

    for number in numbers:
        if number == 0:
            break

        position += 1

        if min_value is None or number < min_value:
            min_value = number
            min_position = position

    return min_position

def sum_valid_pairs(pairs):
    total = 0

    for first, second in pairs:
        if first == 0 and second == 0:
            break

        if first % 2 == 1 and second % 2 == 0:
            total += first + second

    return total

def filter_numbers(x, y, a, b):
    result = []

    for number in range(x, y + 1):
        first_digit = number // 100
        last_digit = number % 10

        if first_digit != a or last_digit != b:
            result.append(number)

    return result

def find_second_smallest(numbers):
    values = []

    for number in numbers:
        if number == 0:
            break
        values.append(number)

    if len(values) < 2:
        return 0

    smallest = min(values)
    second_smallest = None

    for value in values:
        if value != smallest and (second_smallest is None or value < second_smallest):
            second_smallest = value

    return second_smallest if second_smallest is not None else 0
